                <!-- ROW 1 -->
                <div class="dest-row row1-card1">

                    <!-- Left 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://timetoceylon.com/resources/img/destinations/minneriya/minneriya1.webp" alt="MINNERIYA NATIONAL PARK">
