                    <!-- Left 40%: single image -->
                    <div class="dest-col col-img">
                        <div class="main-img-wrap">
                            <img src="https://timetoceylon.com/resources/img/destinations/kalpitiya/kalpitiya1.webp" alt="KALPITIYA">
